def _risk(rid, title, statement, assets, threat, gap, obs, owner, inherent_l, impacts, existing, current, option, controls, actions, target, acceptance="-"):
    return dict(id=rid, title=title, statement=statement, assets=assets, threat=threat, gap=gap, obs=obs or "-", owner=owner, li=inherent_l, impacts=impacts,
                existing=existing, lc=current[0], ic=current[1], option=option, controls=controls, actions=actions, lt=target[0], it=target[1], acceptance=acceptance)


